 public static function listScheduleForUser(string $uid,?string $from=null,?string $to=null):array{$m=self::r('GET','group_memberships?user_id=eq.'.rawurlencode($uid).'&is_active=eq.true&select=group_id');$ids=[];foreach($m as $x)$ids[]=(string)$x['group_id'];$ids=array_values(array_unique($ids));if(!$ids)return [];$r=self::r('GET','schedules?group_id=in.('.rawurlencode(self::q($ids)).')&select='.rawurlencode('id,group_id,semester,version,created_at,schedule_entries(id,subject_id,date,start_time,end_time,type,room,building,notes,is_cancelled,teacher,academic_hours,week_parity,recurrence_group,parent_entry_id,source_detail,event_kind,is_makeup,session_id,source)').'&order=group_id.asc,semester.asc.nullslast,version.desc');$out=[];$latest=[];foreach($r as $x){$k=$x['group_id'].':'.($x['semester']??0);if(!isset($latest[$k]))$latest[$k]=$x;}foreach($latest as $s)foreach($s['schedule_entries']??[] as $e){$d=(string)($e['date']??'');if(($from&&$d<$from)||($to&&$d>$to))continue;$e['schedule_id']=$s['id'];$e['group_id']=$s['group_id'];$e['semester']=$s['semester'];$e['version']=$s['version'];$out[]=$e;}return $out;}
 public static function replaceSchedule(array $p):array{$g=trim((string)($p['group_id']??''));if($g==='')throw new \InvalidArgumentException('group_id is required');$s=($p['semester']??'')===''?null:(int)$p['semester'];$existing=self::r('GET','schedules?group_id=eq.'.rawurlencode($g).($s===null?'&semester=is.null':'&semester=eq.'.(int)$s).'&select=id,version&order=version.desc&limit=1');$v=$existing?((int)($existing[0]['version']??0)+1):1;self::r('PATCH','schedules?group_id=eq.'.rawurlencode($g).($s===null?'&semester=is.null':'&semester=eq.'.(int)$s).'&is_active=eq.true',['is_active'=>false],['Prefer: return=minimal']);$x=self::r('POST','schedules',['group_id'=>$g,'academic_year_id'=>$p['academic_year_id']??null,'semester'=>$s,'version'=>$v,'is_active'=>true],['Prefer: return=representation']);$sid=$x[0]['id']??null;if(!$sid)throw new \RuntimeException('Could not create schedule');$n=0;foreach((array)($p['entries']??[]) as $e){$d=trim((string)($e['date']??''));$a=trim((string)($e['start_time']??$e['startTime']??''));$b=trim((string)($e['end_time']??$e['endTime']??''));if(!$d||!$a||!$b)continue;self::r('POST','schedule_entries',['schedule_id'=>$sid,'subject_id'=>$e['subject_id']??null,'date'=>$d,'start_time'=>$a,'end_time'=>$b,'type'=>$e['type']??'other','room'=>$e['room']??null,'building'=>$e['building']??null,'notes'=>$e['notes']??null,'is_cancelled'=>(bool)($e['is_cancelled']??false),'teacher'=>$e['teacher']??null,'academic_hours'=>isset($e['academic_hours'])?(int)$e['academic_hours']:null,'week_parity'=>$e['week_parity']??null,'recurrence_group'=>$e['recurrence_group']??null,'parent_entry_id'=>$e['parent_entry_id']??null,'source_detail'=>$e['source_detail']??null,'event_kind'=>$e['event_kind']??'class','is_makeup'=>(bool)($e['is_makeup']??false),'session_id'=>$e['session_id']??null,'source'=>$e['source']??'official'],['Prefer: return=minimal']);$n++;}return ['schedule_id'=>$sid,'group_id'=>$g,'semester'=>$s,'version'=>$v,'entries_saved'=>$n];}
 public static function listHomeworksForUser(string $uid):array{$m=self::r('GET','group_memberships?user_id=eq.'.rawurlencode($uid).'&is_active=eq.true&select=group_id');$ids=[];foreach($m as $x)$ids[]=(string)$x['group_id'];$f=['group_id=is.null'];if($ids)$f[]='group_id=in.('.self::q(array_unique($ids)).')';$h=self::r('GET','homeworks?or=('.implode(',',$f).')&select=id,title,description,due_at,subject_id,group_id,created_at&order=due_at.asc.nullslast');$out=[];$hi=[];foreach($h as $x)$hi[]=(string)$x['id'];$subs=[];if($hi)foreach(self::r('GET','homework_submissions?homework_id=in.('.rawurlencode(self::q($hi)).')&user_id=eq.'.rawurlencode($uid).'&select=id,homework_id,status,grade,submitted_at') as $x)$subs[(string)$x['homework_id']]=$x;foreach($h as $x){if(isset($subs[(string)$x['id']])){$z=$subs[(string)$x['id']];$x['submission_id']=$z['id'];$x['my_status']=$z['status'];$x['grade']=$z['grade'];$x['submitted_at']=$z['submitted_at'];}$out[]=$x;}return $out;}
 public static function listHomeworksForReview():array{$h=self::r('GET','homeworks?select=id,title,description,due_at,subject_id,group_id,created_at&order=due_at.asc.nullslast,created_at.desc');$hi=[];foreach($h as $x)$hi[]=(string)$x['id'];$sub=[];foreach(self::r('GET','homework_submissions?homework_id=in.('.rawurlencode(self::q($hi)).')&select=id,homework_id,user_id,status,text_answer,file_id,grade,teacher_comment,submitted_at') as $x)$sub[(string)$x['homework_id']][]=$x;$out=[];foreach($h as $x){$list=$sub[(string)$x['id']]??[null];foreach($list as $z){$r=$x;if(is_array($z)){$r['submission_id']=$z['id'];$r['student_id']=$z['user_id'];$r['submission_status']=$z['status'];$r['text_answer']=$z['text_answer'];$r['file_id']=$z['file_id'];$r['grade']=$z['grade'];$r['teacher_comment']=$z['teacher_comment'];$r['submitted_at']=$z['submitted_at'];}$out[]=$r;}}return $out;}
